```rust
fn percentile_sorted(sorted: &[u64], percentile: f64) -> u64 {
    let len = sorted.len();
    if len == 0 {
        return 0;
    }
    if len == 1 {
        return sorted[0];
    }
    let rank = ((len - 1) as f64 * percentile.clamp(0.0, 1.0)).round() as usize;
    sorted[rank.min(len - 1)]
}
```
